# R reference values for gaply_core::stats_dist, the methods' distribution
# functions at large degrees of freedom (Research OS, Phase 8E, decision 276).
#
# Run by its full path, from anywhere:
#
#   /usr/local/bin/Rscript make_dist_fixtures.R
#
# R is the reference, run outside Gaply (ADR-008): nothing of R is copied into
# Gaply. Base R only. Writes, next to this script, four files, each with a
# '#' header naming this script, R's version and the call, then a CSV body
# with every number as %.17g:
#
#   t_quantile.csv      df,q          q = qt(0.975, df)
#   normal_quantile.csv p,q           q = qnorm(0.975)
#   t_p.csv             df,t,p        p = 2 * pt(|t|, df, lower.tail = FALSE)
#   f_p.csv             df1,df2,f,p   p = pf(F, df1, df2, lower.tail = FALSE)
#
# As 8A's make_8a_refs.R did, a statistic is placed at a target p through
# R's quantile function, and R's p is then computed from that statistic, so
# the row holds R's p of the exact double Gaply is given, not the target.
#
# Synthetic grids only. No manuscript or data of anyone's is read.

args <- commandArgs(trailingOnly = FALSE)
script <- sub("^--file=", "", args[grep("^--file=", args)])
here <- dirname(normalizePath(script))

f17 <- function(x) sprintf("%.17g", as.numeric(x))

emit <- function(name, what, call, frame) {
  path <- file.path(here, name)
  writeLines(c(
    sprintf("# R's %s, for gaply_core::stats_dist (Research OS, Phase 8E).", what),
    "# Generated by /usr/local/bin/Rscript make_dist_fixtures.R (do not edit by hand).",
    sprintf("# %s, %s; %s.", R.version.string, R.version$arch, call)), path)
  write.table(frame, path, sep = ",", quote = FALSE, row.names = FALSE, append = TRUE)
  cat(sprintf("%s: %d rows\n", name, nrow(frame)))
}

# 1. qt(0.975, df): 20 df across the switch at 1e4 and up to 1e7.
q_df <- c(1000, 2500, 4998, 10000, 10000.5, 10001, 10002, 12345.6, 15000, 20000,
          30000, 50000, 99998, 1e5, 2e5, 5e5, 1e6, 2e6, 5e6, 1e7)
emit("t_quantile.csv", "qt(0.975, df)", "qt(0.975, df)",
     data.frame(df = f17(q_df), q = f17(qt(0.975, q_df))))

# 2. qnorm(0.975).
emit("normal_quantile.csv", "qnorm(0.975)", "qnorm(p)",
     data.frame(p = f17(0.975), q = f17(qnorm(0.975))))

# 3. The two-tailed t p: 13 df, 17 fixed |t| and 9 |t| placed at a target p.
p_df <- c(10000, 10000.5, 10001, 15000, 20000, 50000, 99998, 1e5, 2e5, 5e5, 1e6, 5e6, 1e7)
t_fixed <- c(0, 0.001, 0.5, 1, 1.5, 1.96, 2, 2.5, 3, 4, 5, 6, 8, 10, 15, 20, 30)
p_target <- c(0.05, 1e-3, 1e-6, 1e-12, 1e-20, 1e-50, 1e-100, 1e-200, 1e-300)
t_rows <- list()
for (df in p_df) {
  t_at <- c(t_fixed, qt(p_target / 2, df, lower.tail = FALSE))
  t_rows[[length(t_rows) + 1]] <- data.frame(
    df = f17(df), t = f17(t_at), p = f17(2 * pt(t_at, df, lower.tail = FALSE)))
}
emit("t_p.csv", "two-tailed p of Student's t", "2 * pt(abs(t), df, lower.tail = FALSE)",
     do.call(rbind, t_rows))

# 4. The upper-tail F p: df1 = 1 on 16 df2, df1 = 2 and 3 on 3 df2 each; F = 0
#    and F placed at 8 upper-tail targets.
f_grid <- rbind(
  data.frame(df1 = 1, df2 = c(5000, 7500, 9999, 10000, 10001, 15000, 20000, 30000, 50000,
                               75000, 99998, 1e5, 2e5, 5e5, 1e6, 1e7)),
  data.frame(df1 = 2, df2 = c(10001, 1e5, 1e6)),
  data.frame(df1 = 3, df2 = c(10001, 1e5, 1e6)))
f_target <- c(0.5, 0.05, 1e-3, 1e-6, 1e-12, 1e-50, 1e-100, 1e-300)
f_rows <- list()
for (i in seq_len(nrow(f_grid))) {
  df1 <- f_grid$df1[i]
  df2 <- f_grid$df2[i]
  f_at <- c(0, qf(f_target, df1, df2, lower.tail = FALSE))
  f_rows[[length(f_rows) + 1]] <- data.frame(
    df1 = f17(df1), df2 = f17(df2), f = f17(f_at),
    p = f17(pf(f_at, df1, df2, lower.tail = FALSE)))
}
emit("f_p.csv", "upper-tail p of F", "pf(F, df1, df2, lower.tail = FALSE)",
     do.call(rbind, f_rows))

cat(sprintf("%s, %s\n", R.version.string, R.version$arch))
